import { ensureAdminAccess } from "./admin-access";
export const handleAdminAuthUser = async ({ user, mountSso, toast, setCurrentUser, onSignedOut, onDenied, onAuthorized, reason = "", } = {}) => {
    if (!user) {
        setCurrentUser?.(null);
        onSignedOut?.();
        mountSso?.("login", "", "auth:logged-out");
        return false;
    }
    setCurrentUser?.({
        email: user.email || "",
        photoURL: user.photoURL || "",
    });
    const isAllowed = await ensureAdminAccess({
        user,
        mountSso,
        toast,
        onDenied,
        onPermissionsError: onDenied,
    });
    if (!isAllowed)
        return false;
    onAuthorized?.(user, reason);
    return true;
};
